def compute(vars):
    receivables = vars["v2"]
    doubtful_allowance = vars["v1"]

    if receivables == 0:
        return None

    percentage = (-doubtful_allowance / receivables) * 100

    return {
        "value": percentage,
        "trace": {
            "doubtful_receivables": -doubtful_allowance,
            "trade_and_other_accounts_receivable": receivables,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
